import { Link } from 'react-router-dom';

function Nav() {
    return (

        <div className="navbar">

            <div className="logo">
                CodeLearn
            </div>

            <div className="nav-links">

                <Link to="/">
                    Home
                </Link>

                <Link to="/about">
                    About
                </Link>

                <Link to="/contact">
                    Contact
                </Link>

            </div>
        </div>


        // ================================================

        
    );
}

export default Nav;
